public object FfiConverterTypeWaddleClient: FfiConverter<WaddleClient, Long> {
    override fun lower(value: WaddleClient): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): WaddleClient {
        return WaddleClient(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): WaddleClient {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: WaddleClient) = 8UL

    override fun write(value: WaddleClient, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



